// src/data/reactions.rs

use super::common::{Condition, ProcessType, StoichPoint};
use bevy::{asset::Asset, reflect::TypePath};
use serde::Deserialize;

/// The Asset definition. This is what Bevy's AssetServer will load.
///
/// `authored_reactions.ron` (generated by `tools/data/gen_authored.py`) holds every reaction
/// in the game, and the progression: the epochs, the starting inventory, and the milestones
/// that unlock vessels and hand out materials.
#[derive(Debug, Deserialize, Asset, TypePath, Clone, Default)]
pub struct Reactions {
    pub reactions: Vec<Reaction>,
    /// Tech-tree epochs, in order. Authored reactions refer to them by index.
    #[serde(default)]
    pub epochs: Vec<EpochDef>,
    /// Substance ids the player starts a new game with.
    #[serde(default)]
    pub start: Vec<u32>,
    /// Discovery-driven unlocks.
    #[serde(default)]
    pub milestones: Vec<Milestone>,
}

/// One column of the tech tree.
#[derive(Debug, Deserialize, Clone)]
pub struct EpochDef {
    pub name: String,
    /// Rough period, e.g. "to 1200 BCE".
    #[serde(default)]
    pub era: String,
    /// One line for the banner shown when the player reaches this era.
    #[serde(default)]
    pub blurb: String,
}

/// When the player first discovers `on`, unlock the listed vessels and hand over the
/// listed raw materials.
#[derive(Debug, Deserialize, Clone)]
pub struct Milestone {
    pub on: u32,
    #[serde(default)]
    pub unlock: Vec<ProcessType>,
    #[serde(default)]
    pub grant: Vec<u32>,
    /// Shown to the player when the milestone fires.
    #[serde(default)]
    pub message: Option<String>,
}

/// Defines a single, valid chemical reaction "recipe".
/// Based on the GDD's technical implementation plan.
#[derive(Debug, Deserialize, Clone)]
pub struct Reaction {
    /// Unique ID for this reaction.
    pub id: u32,
    /// A human-readable name, e.g., "Haber-Bosch Process".
    pub name: String,
    /// A list of reactants and their molar amounts.
    pub reactants: Vec<StoichPoint>,
    /// A list of products and their molar amounts.
    pub products: Vec<StoichPoint>,
    /// The primary process required to trigger this reaction.
    pub process: ProcessType,

    /// A list of other conditions that must be met.
    #[serde(default)] // Makes this field optional in the RON file
    pub conditions: Vec<Condition>,

    /// The standard enthalpy change for the reaction in kJ/mol.
    /// A negative value is exothermic (releases heat).
    /// A positive value is endothermic (requires heat).
    pub enthalpy_change_kj_mol: f32,

    /// The activation energy required in kJ/mol.
    /// This determines the base rate of reaction.
    pub activation_energy_kj: f32,

    // --- Reaction Library enrichment (authored/named reactions) ---
    /// A blurb: history, facts, significance.
    #[serde(default)]
    pub description: Option<String>,
    /// External reference links as (label, url) pairs (Wikipedia, ...).
    #[serde(default)]
    pub references: Vec<(String, String)>,

    /// Tech-tree epoch index (an era of `Reactions::epochs`); every reaction sits in one.
    pub epoch: u8,
}

impl Reaction {
    /// The catalyst this reaction needs in the Catalyst Bed's slot, if any.
    pub fn required_catalyst(&self) -> Option<u32> {
        self.conditions.iter().find_map(|c| match c {
            Condition::RequiresCatalyst(id) => Some(*id),
            _ => None,
        })
    }
}
